package ec.edu.monster.servicios;

import ec.edu.monster.configuracion.ConfiguracionSoap;
import ec.edu.monster.modelos.Modelos.*;
import java.io.*; import java.math.BigDecimal; import java.net.*; import java.nio.charset.StandardCharsets; import java.util.*;
import javax.xml.XMLConstants; import javax.xml.parsers.DocumentBuilderFactory; import org.w3c.dom.*;

/** Infraestructura SOAP Android. Nunca se invoca desde el hilo principal. */
public final class ClienteSoapEureka {
 private static final String NS="http://servicios.monster.edu.ec/";
 public Sesion login(String u,String p)throws Exception{Document d=call("LoginServicio/LoginControlador","login",null,"<usuario>"+e(u)+"</usuario><contrasenia>"+e(p)+"</contrasenia>");fault(d);Element x=one(d,"respuestaLogin");return new Sesion(t(x,"token"),t(x,"usuarioId"),t(x,"usuarioNombre"));}
 public List<Cuenta> cuentas(String token)throws Exception{Document d=call("CuentaServicio/CuentaControlador","listarCuentas",token,"");fault(d);List<Cuenta> r=new ArrayList<>();for(Element x:many(d,"return"))r.add(new Cuenta(t(x,"cuentaId"),t(x,"cuentaNumero"),n(t(x,"cuentaSaldo")),t(x,"cuentaEstado"),t(x,"sucursalId")));return r;}
 public Map<String,String> disponibilidades(String token)throws Exception{Document d=call("CuentaServicio/CuentaControlador","listarDisponibilidades",token,"");fault(d);Map<String,String> r=new HashMap<>();for(Element x:many(d,"disponibilidad"))r.put(t(x,"cuentaId"),t(x,"estado"));return r;}
 public List<Cliente> clientesParaCuenta(String token)throws Exception{Document d=call("CuentaServicio/CuentaControlador","listarClientesParaCuenta",token,"");fault(d);List<Cliente> r=new ArrayList<>();for(Element x:many(d,"cliente"))r.add(new Cliente(t(x,"usuarioId"),t(x,"nombreCompleto"),t(x,"usuario")));return r;}
 public Cuenta crearCuentaParaUsuario(String token,String usuarioId)throws Exception{Document d=call("CuentaServicio/CuentaControlador","crearCuentaParaUsuario",token,"<usuarioId>"+e(usuarioId)+"</usuarioId>");fault(d);Element x=one(d,"cuenta");return new Cuenta(t(x,"cuentaId"),t(x,"cuentaNumero"),n(t(x,"cuentaSaldo")),t(x,"cuentaEstado"),t(x,"sucursalId"));}
 public Perfil perfil(String token,String usuarioId)throws Exception{Document d=call("UsuarioServicio/UsuarioControlador","obtenerPerfilBancario",token,"<usuarioId>"+e(usuarioId)+"</usuarioId>");fault(d);Element p=one(d,"perfil"),u=one(p,"usuario");List<Cuenta> cuentas=new ArrayList<>();for(Element x:many(p,"cuentas"))cuentas.add(new Cuenta(t(x,"cuentaId"),t(x,"cuentaNumero"),n(t(x,"cuentaSaldo")),t(x,"cuentaEstado"),t(x,"sucursalId")));return new Perfil(t(u,"usuarioNombre")+" "+t(u,"usuarioApellido"),t(u,"usuarioUsuario"),t(u,"usuarioTelefono"),cuentas);}
 public List<Movimiento> movimientos(String token,String cuenta)throws Exception{Document d=call("TransaccionServicio/TransaccionControlador","listarPorCuenta",token,"<cuentaId>"+e(cuenta)+"</cuentaId>");fault(d);List<Movimiento> r=new ArrayList<>();for(Element x:many(d,"transacciones"))r.add(new Movimiento(t(x,"transaccionId"),t(x,"transaccionTipo"),n(t(x,"transaccionSaldo")),t(x,"transaccionCreadoEn")));return r;}
 public void transferir(String token,String origen,String destino,BigDecimal monto)throws Exception{Document d=call("TransaccionServicio/TransaccionControlador","realizarTransferencia",token,"<cuentaOrigenId>"+e(origen)+"</cuentaOrigenId><cuentaDestinoId>"+e(destino)+"</cuentaDestinoId><monto>"+monto.toPlainString()+"</monto>");fault(d);}
 public void movimiento(String token,String tipo,String cuenta,BigDecimal monto)throws Exception{Document d=call("TransaccionServicio/TransaccionControlador","generarTransaccion",token,"<tipo>"+e(tipo)+"</tipo><cuentaId>"+e(cuenta)+"</cuentaId><monto>"+monto.toPlainString()+"</monto>");fault(d);}
 public void reversar(String token,String transaccionId)throws Exception{Document d=call("TransaccionServicio/TransaccionControlador","reversarTransaccion",token,"<transaccionId>"+e(transaccionId)+"</transaccionId>");fault(d);}
 private Document call(String srv,String op,String token,String body)throws Exception{String h=token==null?"":"<ser:token>"+e(token)+"</ser:token>";String x="<?xml version=\"1.0\"?><soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\" xmlns:ser=\""+NS+"\"><soap:Header>"+h+"</soap:Header><soap:Body><ser:"+op+">"+body+"</ser:"+op+"></soap:Body></soap:Envelope>";HttpURLConnection c=(HttpURLConnection)new URL(ConfiguracionSoap.urlBase()+"/"+srv).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(8000);c.setReadTimeout(20000);c.setDoOutput(true);c.setRequestProperty("Content-Type","text/xml; charset=utf-8");try(OutputStream o=c.getOutputStream()){o.write(x.getBytes(StandardCharsets.UTF_8));}InputStream i=c.getResponseCode()>=400?c.getErrorStream():c.getInputStream();DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING,true);f.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD,"");f.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");f.setNamespaceAware(true);return f.newDocumentBuilder().parse(i);}
 private static void fault(Document d)throws Exception{NodeList x=d.getElementsByTagNameNS("*","faultstring");if(x.getLength()>0)throw new IllegalStateException(x.item(0).getTextContent());}
 private static Element one(Node n,String q){NodeList x=n instanceof Document?((Document)n).getElementsByTagNameNS("*",q):((Element)n).getElementsByTagNameNS("*",q);return x.getLength()==0?null:(Element)x.item(0);}
 private static List<Element> many(Node n,String q){NodeList x=n instanceof Document?((Document)n).getElementsByTagNameNS("*",q):((Element)n).getElementsByTagNameNS("*",q);List<Element> r=new ArrayList<>();for(int i=0;i<x.getLength();i++)r.add((Element)x.item(i));return r;}
 private static String t(Element e,String q){Element x=one(e,q);return x==null?"":x.getTextContent();} private static BigDecimal n(String x){try{return new BigDecimal(x);}catch(Exception e){return BigDecimal.ZERO;}} private static String e(String x){return x==null?"":x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
}
